begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'CHEMISTRY_ACID_BASE';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 9, 'Interpretar pH sem extrapolar o que ele não mede', 'pH compara acidez/basicidade em solução aquosa. A escala é logarítmica; indicadores dão faixas, e neutralização depende das quantidades e da reação. Uma leitura de pH não substitui avaliação de segurança.', '## 1. O que o pH compara
Em soluções aquosas, o pH está relacionado à atividade dos íons H+. Em condições usuais de comparação escolar, valores abaixo de 7 indicam caráter ácido, 7 é referência neutra e valores acima de 7 indicam caráter básico. Uma unidade de diferença corresponde a uma variação de dez vezes na atividade de H+; portanto, uma diferença de duas unidades corresponde a cem vezes. O pH não informa sozinho a quantidade total de ácido presente nem identifica todas as substâncias da amostra.

## 2. Indicadores e instrumentos
Um indicador muda de cor em uma faixa de pH. Compare a cor com a escala fornecida e registre uma faixa compatível, não um decimal exato que o método não consegue distinguir. Um medidor digital também exige procedimento correto, calibração adequada e amostra identificada. Temperatura, contaminação, eletrodo e coleta podem alterar a leitura. Registre método, condições e incerteza.

## 3. Neutralização depende da reação
Ácido e base podem reagir, mas volumes iguais não garantem quantidades químicas equivalentes: concentração, composição e proporção da equação importam. Em um exemplo simples de ácido forte e base forte em proporções estequiométricas, forma-se água e um sal; o resultado não autoriza presumir que qualquer mistura ficou neutra ou segura. O ponto em que o indicador muda de cor é um ponto final operacional; a equivalência é a condição estequiométrica da reação, e os dois pontos podem não coincidir exatamente.

## 4. Dados ambientais e segurança
Uma mudança de pH pode ser relevante para processos químicos e organismos aquáticos. Ainda assim, observar pH diferente e mudança biológica ao mesmo tempo não prova uma causa única: metais, temperatura, oxigênio, vazão e outras condições podem participar. E pH não é uma escala universal de perigo. Risco depende também da substância, concentração, quantidade e exposição. Não prove, toque ou misture amostras ou produtos; atividades práticas só devem ocorrer com material e supervisão apropriados.',
    'Uma amostra A tem pH 4 e uma amostra B tem pH 6, medidas pelo mesmo procedimento. A tem atividade de H+ cem vezes maior que B, pois a diferença de duas unidades corresponde a 10 x 10. Isso permite comparar o caráter ácido naquelas condições, mas não dizer qual amostra contém mais massa total de ácido, identificar as substâncias ou concluir qual é mais perigosa. Para responder essas perguntas seriam necessários dados adicionais sobre composição, concentração e exposição.', array['Conte quantas unidades separam os valores; cada unidade corresponde a um fator dez na atividade de H+.', 'Leia a faixa do indicador e identifique o método antes de comparar resultados.', 'Para neutralização, verifique concentração, composição e proporção da reação, não apenas volume.', 'Separe o que a medida mostra do que ainda não permite concluir sobre composição ou risco.']::text[], 13, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v9-chemistry-acid-base-expansion-v9","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Ler uma escala numérica e comparar valores.","Distinguir observação, hipótese e informação que ainda falta."],"key_concepts":["pH é logarítmico e ligado à atividade/concentração de H+ em solução aquosa.","Indicadores mudam de cor em intervalos, não necessariamente em um valor exato.","Neutralização depende da quantidade química e da reação.","pH sozinho não identifica composição nem determina segurança."],"progression":[{"stage":"FOUNDATION","focus":"Classificar valores e interpretar mudanças em escala logarítmica.","questionIds":["v5-chem-ab-probe-01","v5-chem-ab-probe-03"]},{"stage":"APPLICATION","focus":"Interpretar indicadores, instrumentos, neutralização e limites da medida.","questionIds":["v5-chem-ab-practice-01","v5-chem-ab-practice-11"]},{"stage":"TRANSFER","focus":"Analisar dados ambientais e decisões sem extrapolar causalidade ou segurança.","questionIds":["v5-chem-ab-transfer-01","v5-chem-ab-transfer-07","v9-chemistry-acid-base-expansion-v9-051","v9-chemistry-acid-base-expansion-v9-052","v9-chemistry-acid-base-expansion-v9-053","v9-chemistry-acid-base-expansion-v9-054","v9-chemistry-acid-base-expansion-v9-055","v9-chemistry-acid-base-expansion-v9-056","v9-chemistry-acid-base-expansion-v9-057","v9-chemistry-acid-base-expansion-v9-058","v9-chemistry-acid-base-expansion-v9-059","v9-chemistry-acid-base-expansion-v9-060","v9-chemistry-acid-base-expansion-v9-061","v9-chemistry-acid-base-expansion-v9-062","v9-chemistry-acid-base-expansion-v9-063","v9-chemistry-acid-base-expansion-v9-064","v9-chemistry-acid-base-expansion-v9-065","v9-chemistry-acid-base-expansion-v9-066","v9-chemistry-acid-base-expansion-v9-067","v9-chemistry-acid-base-expansion-v9-068","v9-chemistry-acid-base-expansion-v9-069","v9-chemistry-acid-base-expansion-v9-070","v9-chemistry-acid-base-expansion-v9-071","v9-chemistry-acid-base-expansion-v9-072","v9-chemistry-acid-base-expansion-v9-073","v9-chemistry-acid-base-expansion-v9-074","v9-chemistry-acid-base-expansion-v9-075"]},{"stage":"INTEGRATION","focus":"Distinguir pH, capacidade de neutralização, ponto final e equivalência.","questionIds":["v5-chem-ab-lock-01","v5-chem-ab-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar escala, evidência, neutralização e segurança em novos contextos; espaçamento não automatizado.","questionIds":["v5-chem-ab-review-01","v5-chem-ab-review-09"]}],"micro_explanations":[{"trigger":"LOG_SCALE_AS_LINEAR","text":"Uma unidade de pH representa fator dez na atividade de H+. Duas unidades representam 10 x 10, não uma diferença aditiva de duas vezes."},{"trigger":"INDICATOR_AS_EXACT_METER","text":"A cor é comparada com uma faixa de referência. Registre a faixa e o método, sem inventar casas decimais."},{"trigger":"VOLUME_AS_STOICHIOMETRY","text":"Volumes iguais podem conter quantidades diferentes de reagente. Compare concentração, composição e proporção da equação."},{"trigger":"PH_AS_HAZARD_SCORE","text":"pH é uma propriedade da solução, não uma avaliação completa de risco. Composição, concentração e exposição também importam."}],"remediations":[{"misconception":"LINEAR_PH_SCALE","prompt":"Monte uma tabela para diferenças de 1, 2 e 3 unidades usando 10, 10 x 10 e 10 x 10 x 10; depois compare as amostras."},{"misconception":"COLOR_IS_EXACT_VALUE","prompt":"Registre a escala do indicador, a cor observada e o intervalo compatível. Explique a resolução limitada."},{"misconception":"EQUAL_VOLUME_MEANS_NEUTRAL","prompt":"Converta volume e concentração em quantidade de matéria e confira a proporção da reação antes de prever o resultado."},{"misconception":"PH_ALONE_DETERMINES_RISK","prompt":"Liste composição, concentração, quantidade e via de exposição como dados necessários; não proponha teste por contato ou mistura."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"What is pH?","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/goldkingmine/what-ph","accessedOn":"2026-10-13","supports":["pH classification","neutral reference","logarithmic comparison between adjacent whole values"],"use":"Fact-check only; scenarios, wording, exercises and explanations are original."},{"title":"pH (CADDIS)","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/caddis/ph","accessedOn":"2026-10-13","supports":["pH relationship to hydrogen ion activity","effects and contributing factors in aquatic systems","evidence-based causal assessment"],"use":"Fact-check only; no source wording, figures, thresholds or species examples copied."}],"copyright_note":"No source wording, questions, figures, data, species examples or thresholds were copied. Scenarios are hypothetical and authored for this package. No laboratory instruction authorizes unsupervised chemical handling. Lote V9 autoral com 100 questões, progressão e revisão pedagógica pendente; publicação mantida em STAGING.","objective":"Interpretar pH e indicadores como evidências sobre soluções, relacionando medidas e neutralização sem inferir composição, risco ou segurança apenas pelo rótulo ácido/base.","common_mistake":"Ler diferenças de pH como lineares, registrar precisão maior que a escala do indicador ou supor que volumes iguais neutralizam qualquer ácido e base.","estimated_minutes":13}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 9
     and metadata->>'content_id' = 'v9-chemistry-acid-base-expansion-v9' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-chem-ab-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"PH_COMPARACAO_LAB","statement":"Duas amostras aquosas são medidas pelo mesmo método: A tem pH 4 e B tem pH 5. Qual comparação é compatível com a escala de pH?","options":["A atividade de H+ em A é cerca de dez vezes a de B.","A atividade de H+ em A é exatamente uma unidade maior que a de B.","B tem dez vezes mais atividade de H+ que A.","As amostras têm a mesma acidez porque diferem por apenas um ponto."],"correctAnswer":"A atividade de H+ em A é cerca de dez vezes a de B.","explanation":"Uma unidade de pH representa fator dez na atividade de H+; o valor menor corresponde à atividade maior.","hint":"A escala é logarítmica: uma unidade não significa uma diferença aditiva simples.","errorFocus":"LINEAR_PH_SCALE","misconceptions":{"A atividade de H+ em A é exatamente uma unidade maior que a de B.":["PH_DIFFERENCE_TREATED_AS_LINEAR"]},"position":1},{"id":"v5-chem-ab-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"INDICADOR_FAIXA_INICIAL","statement":"Uma fita indicadora apresenta cor compatível com a faixa de pH 5 a 6 segundo a escala do fabricante. Qual registro respeita melhor o método?","options":["A amostra tem exatamente pH 5,43.","A amostra é neutra porque a fita mudou de cor.","A amostra ficou aproximadamente na faixa de pH 5–6 pelo indicador utilizado.","O resultado identifica quais substâncias estão dissolvidas."],"correctAnswer":"A amostra ficou aproximadamente na faixa de pH 5–6 pelo indicador utilizado.","explanation":"A leitura visual permite comparar uma faixa com a escala; não fornece precisão decimal nem identifica a composição.","hint":"Observe a resolução que a própria escala oferece.","errorFocus":"COLOR_IS_EXACT_VALUE","misconceptions":{"A amostra tem exatamente pH 5,43.":["FALSE_PRECISION_FROM_COLOR"]},"position":2},{"id":"v5-chem-ab-probe-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"ESCALA_SOLUCAO_AQUOSA","statement":"Em uma comparação escolar de soluções aquosas à temperatura ambiente, qual amostra apresenta caráter básico segundo a escala usual?","options":["A amostra de pH 6.","A amostra de pH 7.","Não é possível comparar nenhum valor de pH.","A amostra de pH 8."],"correctAnswer":"A amostra de pH 8.","explanation":"Na referência escolar usual para soluções aquosas à temperatura ambiente, pH acima de 7 indica caráter básico.","hint":"Localize os valores em relação à referência neutra 7.","errorFocus":"PH_SCALE_CLASSIFICATION","misconceptions":{"A amostra de pH 6.":["ACID_BASE_DIRECTION_REVERSED"]},"position":3},{"id":"v5-chem-ab-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"PH_DIFERENCA_DOIS_PONTOS","statement":"Em condições comparáveis, uma solução tem pH 3 e outra tem pH 5. Aproximadamente quantas vezes maior é a atividade de H+ na primeira?","options":["100 vezes.","2 vezes.","10 vezes.","A mesma atividade."],"correctAnswer":"100 vezes.","explanation":"A diferença é de duas unidades; cada unidade corresponde a fator dez, então 10 x 10 = 100.","hint":"Transforme a diferença de duas unidades em dois fatores de dez.","errorFocus":"LOG_SCALE_MULTIPLIER","misconceptions":{"2 vezes.":["PH_GAP_AS_ADDITIVE_RATIO"]},"position":1},{"id":"v5-chem-ab-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"CALIBRACAO_MEDIDOR","statement":"Um medidor digital foi usado para comparar duas amostras, mas a equipe não verificou sua calibração e o eletrodo estava sujo. Qual é a melhor decisão antes de interpretar pequenas diferenças?","options":["Manter todos os valores com duas casas porque o visor as mostra.","Escolher o valor que combina com a hipótese inicial.","Repetir a medição após limpeza e calibração conforme o procedimento do instrumento, registrando as condições.","Concluir que a amostra com menor valor é necessariamente mais perigosa."],"correctAnswer":"Repetir a medição após limpeza e calibração conforme o procedimento do instrumento, registrando as condições.","explanation":"A resolução exibida não garante exatidão; calibração, condição do eletrodo e protocolo influenciam a confiabilidade.","hint":"Separe resolução do visor de confiabilidade da medida.","errorFocus":"DISPLAY_PRECISION_AS_ACCURACY","misconceptions":{"Manter todos os valores com duas casas porque o visor as mostra.":["INSTRUMENT_DIGITS_AS_VALID_PRECISION"]},"position":2},{"id":"v5-chem-ab-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"INDICADOR_COR_LIMITE","statement":"A cor de um indicador fica entre duas referências da cartela. Qual conclusão é mais defensável?","options":["O valor exato é a média das duas referências, sem incerteza.","A leitura é aproximada e deve ser registrada como intervalo entre referências compatíveis.","A solução necessariamente contém quantidades iguais de ácido e base.","A cor permite identificar todos os íons presentes."],"correctAnswer":"A leitura é aproximada e deve ser registrada como intervalo entre referências compatíveis.","explanation":"Comparação visual tem resolução limitada; o registro deve refletir essa incerteza e o método usado.","hint":"Não atribua ao indicador mais precisão do que ele possui.","errorFocus":"INDICATOR_RANGE_IGNORED","misconceptions":{"O valor exato é a média das duas referências, sem incerteza.":["INTERPOLATION_WITHOUT_EVIDENCE"]},"position":3},{"id":"v5-chem-ab-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"PH_CAPACIDADE_TAMPONANTE","statement":"Duas águas têm inicialmente pH parecido. Após receberem a mesma pequena quantidade de ácido em um teste controlado, o pH de uma muda menos. O que esse resultado sugere?","options":["A capacidade de resistir à mudança de pH pode diferir, mesmo que os valores iniciais fossem parecidos.","As duas águas têm necessariamente a mesma composição e capacidade de neutralização.","A água que mudou menos não contém nenhuma substância dissolvida.","O pH inicial determina sozinho quanto o valor mudará após qualquer adição."],"correctAnswer":"A capacidade de resistir à mudança de pH pode diferir, mesmo que os valores iniciais fossem parecidos.","explanation":"O pH descreve o estado medido; capacidade de neutralização depende de componentes da solução e não é determinada apenas pelo valor inicial.","hint":"Compare o valor inicial com a resposta após a mesma adição controlada.","errorFocus":"PH_CONFUSED_WITH_BUFFERING_CAPACITY","misconceptions":{"As duas águas têm necessariamente a mesma composição e capacidade de neutralização.":["SAME_PH_MEANS_SAME_BUFFERING"]},"position":4},{"id":"v5-chem-ab-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"VOLUMES_IGUAIS_REAGENTES","statement":"Uma estudante mistura 20 mL de uma solução ácida com 20 mL de uma básica, sem conhecer concentrações ou composição. O que pode concluir sobre o pH final?","options":["O pH final será exatamente 7 porque os volumes são iguais.","Os volumes iguais não bastam para prever o resultado; concentração, composição e proporção da reação importam.","A solução continuará com o pH inicial do ácido, pois bases não reagem.","A mistura será segura para qualquer uso assim que os volumes forem iguais."],"correctAnswer":"Os volumes iguais não bastam para prever o resultado; concentração, composição e proporção da reação importam.","explanation":"Volumes não determinam sozinhos as quantidades químicas reagentes nem o pH final.","hint":"Pergunte quantos mols de cada reagente há e em qual proporção reagem.","errorFocus":"EQUAL_VOLUME_MEANS_NEUTRAL","misconceptions":{"O pH final será exatamente 7 porque os volumes são iguais.":["VOLUME_CONFUSED_WITH_MOLES"]},"position":5},{"id":"v5-chem-ab-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"EQUACAO_ACIDO_BASE","statement":"No modelo simplificado de uma reação aquosa entre HCl e NaOH em proporções estequiométricas, quais produtos são representados?","options":["Oxigênio e carbono sólido.","Água e cloreto de sódio dissolvido.","Somente ácido clorídrico mais concentrado.","Sódio metálico e cloro gasoso em qualquer condição."],"correctAnswer":"Água e cloreto de sódio dissolvido.","explanation":"Na neutralização simplificada HCl + NaOH → NaCl + H2O, os íons H+ e OH− formam água e os íons restantes compõem o sal em solução.","hint":"Use a equação balanceada e preserve os átomos e íons.","errorFocus":"NEUTRALIZATION_PRODUCTS","misconceptions":{"Sódio metálico e cloro gasoso em qualquer condição.":["AQUEOUS_IONS_TREATED_AS_ELEMENTS"]},"position":6},{"id":"v5-chem-ab-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"SELECT","contextFamily":"ESCOLHA_INDICADOR_TITULACAO","statement":"Em uma análise supervisionada, a mudança de pH esperada ocorre na faixa 6–8. Qual critério orienta a seleção de um indicador?","options":["Escolher qualquer indicador apenas pela cor inicial da amostra.","Escolher um indicador que mude somente muito antes da reação começar.","Usar a cor como substituta da medição de volume e concentração.","Escolher um indicador cuja faixa de mudança de cor cubra a região relevante da curva."],"correctAnswer":"Escolher um indicador cuja faixa de mudança de cor cubra a região relevante da curva.","explanation":"O indicador é escolhido pela faixa de viragem em relação à mudança de pH esperada; cor não substitui as demais medidas.","hint":"Compare a faixa do indicador com a região de mudança do sistema.","errorFocus":"INDICATOR_RANGE_MISMATCH","misconceptions":{"Escolher qualquer indicador apenas pela cor inicial da amostra.":["INDICATOR_CHOSEN_BY_INITIAL_COLOR"]},"position":7},{"id":"v5-chem-ab-practice-08","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"CALCULATE","contextFamily":"PH_ATIVIDADE_H_PLUS","statement":"Se duas soluções aquosas comparáveis diferem por três unidades de pH, qual razão aproximada entre as atividades de H+ corresponde à diferença?","options":["3 para 1, pois basta subtrair os valores.","30 para 1, pois cada unidade vale dez e deve ser somada.","1 para 1, pois valores de pH são apenas rótulos.","1.000 para 1, pois 10 x 10 x 10 = 1.000."],"correctAnswer":"1.000 para 1, pois 10 x 10 x 10 = 1.000.","explanation":"Uma diferença de três unidades corresponde a um fator 10 elevado a 3 na atividade de H+.","hint":"Aplique um fator dez para cada unidade de diferença.","errorFocus":"LOG_SCALE_EXPONENT","misconceptions":{"30 para 1, pois cada unidade vale dez e deve ser somada.":["MULTIPLICATIVE_FACTORS_ADDED"]},"position":8},{"id":"v5-chem-ab-practice-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"RISCO_E_COMPOSICAO","statement":"Uma solução X tem pH menor que uma solução Y. Um estudante conclui que X é necessariamente mais perigosa em qualquer situação. Qual avaliação é correta?","options":["A conclusão é insuficiente: risco também depende da substância, concentração, quantidade e exposição.","A conclusão é sempre correta porque pH é uma escala completa de perigo.","A solução Y é sempre inofensiva se seu pH estiver acima de 7.","O pH identifica a composição química e a via de exposição."],"correctAnswer":"A conclusão é insuficiente: risco também depende da substância, concentração, quantidade e exposição.","explanation":"pH caracteriza uma propriedade da solução, mas não substitui a identificação do material nem uma avaliação de exposição.","hint":"Liste quais informações de risco não aparecem em uma leitura de pH.","errorFocus":"PH_ALONE_DETERMINES_RISK","misconceptions":{"A conclusão é sempre correta porque pH é uma escala completa de perigo.":["PH_MISTAKEN_FOR_HAZARD_SCALE"]},"position":9},{"id":"v5-chem-ab-practice-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"AGUA_RIO_MUDANCA_PH","statement":"Uma equipe registra pH menor em um ponto do rio e menos espécies em uma coleta. Qual afirmação é mais adequada para iniciar a análise?","options":["Os dados justificam investigar uma possível relação, medindo também fatores como metais, temperatura, oxigênio e esforço de coleta.","A coincidência prova que o pH foi a única causa da diferença biológica.","A contagem de espécies permite calcular o pH sem instrumento.","A mudança de pH não pode afetar processos químicos ou biológicos."],"correctAnswer":"Os dados justificam investigar uma possível relação, medindo também fatores como metais, temperatura, oxigênio e esforço de coleta.","explanation":"pH pode influenciar processos e organismos, mas mudanças concomitantes não isolam uma causa; fatores associados também devem ser medidos.","hint":"Separe associação observada de mecanismo causal testado.","errorFocus":"SINGLE_CAUSE_FROM_COVARIATION","misconceptions":{"A coincidência prova que o pH foi a única causa da diferença biológica.":["COINCIDENCE_AS_EXCLUSIVE_CAUSE"]},"position":10},{"id":"v5-chem-ab-practice-11","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"PH_VS_QUANTIDADE_TOTAL","statement":"Duas soluções apresentam o mesmo pH em um ensaio, mas foram preparadas com volumes diferentes. Qual conclusão é segura a partir apenas dessa informação?","options":["As leituras de pH são iguais pelo método usado; não se determina daí a mesma quantidade total de ácido nem composição idêntica.","As duas contêm necessariamente a mesma massa de ácido.","O volume maior sempre tem pH menor.","O pH igual prova que as soluções neutralizam a mesma quantidade de base."],"correctAnswer":"As leituras de pH são iguais pelo método usado; não se determina daí a mesma quantidade total de ácido nem composição idêntica.","explanation":"pH se relaciona à atividade de H+ na solução, mas composição, volume e capacidade de neutralização não são determinados por essa leitura isolada.","hint":"Diferencie a propriedade medida da quantidade total de material na amostra.","errorFocus":"PH_AS_TOTAL_ACID_AMOUNT","misconceptions":{"As duas contêm necessariamente a mesma massa de ácido.":["INTENSIVE_MEASURE_AS_TOTAL_AMOUNT"]},"position":11},{"id":"v5-chem-ab-transfer-01","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"RIACHOS_CAPACIDADE_TAMPONANTE","statement":"Dois riachos recebem a mesma entrada ácida em teste controlado. O pH de um cai mais; a água do outro tem maior capacidade de neutralizar adições. Qual interpretação é mais plausível?","options":["Os dois deveriam mudar exatamente igual porque começaram com o mesmo pH.","O riacho que mudou menos não contém íons dissolvidos.","A capacidade de neutralização pode moderar a mudança de pH, embora composição e outras condições também devam ser verificadas.","A diferença prova que o medidor de um riacho está sempre errado."],"correctAnswer":"A capacidade de neutralização pode moderar a mudança de pH, embora composição e outras condições também devam ser verificadas.","explanation":"Sistemas com capacidade tamponante diferente podem responder de modo distinto à mesma adição; o ensaio precisa controlar outras variáveis.","hint":"Considere não só o valor inicial, mas a resistência do sistema a uma adição.","errorFocus":"INITIAL_PH_AS_BUFFERING_CAPACITY","misconceptions":{"Os dois deveriam mudar exatamente igual porque começaram com o mesmo pH.":["SAME_INITIAL_PH_SAME_RESPONSE"]},"position":1},{"id":"v5-chem-ab-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"EFLUENTE_TRATAMENTO","statement":"Uma estação registra pH próximo da faixa operacional depois de tratamento de um efluente. Qual conclusão é necessária antes de afirmar que a água pode ser liberada para qualquer uso?","options":["A faixa de pH prova que todos os contaminantes foram removidos.","A neutralização converte qualquer substância perigosa em água pura.","Uma leitura de pH dispensa amostragem e análise do efluente.","pH adequado sozinho não demonstra segurança; é preciso verificar contaminantes, critérios aplicáveis e demais parâmetros do tratamento."],"correctAnswer":"pH adequado sozinho não demonstra segurança; é preciso verificar contaminantes, critérios aplicáveis e demais parâmetros do tratamento.","explanation":"pH é apenas um parâmetro. Composição e outros indicadores devem ser avaliados conforme o uso e as normas aplicáveis.","hint":"Pergunte quais contaminantes e propriedades não são medidos pelo pH.","errorFocus":"PH_COMPLIANCE_AS_COMPLETE_SAFETY","misconceptions":{"A faixa de pH prova que todos os contaminantes foram removidos.":["ONE_PARAMETER_AS_COMPLETE_CLEARANCE"]},"position":2},{"id":"v5-chem-ab-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"METAIS_E_PH_CORREGO","statement":"Em um córrego, um ponto apresenta pH menor e maior concentração de metal dissolvido que um ponto de referência. Qual análise é mais cuidadosa?","options":["O pH baixo prova que o metal foi produzido pela água naquele momento.","A concentração de metal é irrelevante sempre que o pH é medido.","pH pode alterar a forma química e a disponibilidade de alguns metais; comparar fontes, medidas repetidas e outros fatores ajuda a avaliar o mecanismo.","A associação demonstra que o metal causou a queda de pH sem possibilidade de outras causas."],"correctAnswer":"pH pode alterar a forma química e a disponibilidade de alguns metais; comparar fontes, medidas repetidas e outros fatores ajuda a avaliar o mecanismo.","explanation":"pH e metais podem interagir, mas a direção causal e as fontes exigem evidência adicional e comparação apropriada.","hint":"Considere interação química e também o que os dados não identificam sobre a origem.","errorFocus":"INTERACTING_STRESSORS_AS_SINGLE_CAUSE","misconceptions":{"A associação demonstra que o metal causou a queda de pH sem possibilidade de outras causas.":["CAUSAL_DIRECTION_ASSUMED"]},"position":3},{"id":"v5-chem-ab-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SOLO_CORRECAO_AGRICOLA","statement":"Um relatório indica pH baixo em alguns pontos de um terreno. Antes de decidir qualquer correção, qual procedimento é mais apropriado?","options":["Aplicar a mesma quantidade de qualquer produto alcalino em toda a área.","Usar apenas a cor de uma planta para calcular a dose necessária.","Concluir que o solo é estéril porque o pH ficou abaixo de 7.","Confirmar amostragem e análise do solo e consultar orientação técnica sobre o cultivo e as condições locais."],"correctAnswer":"Confirmar amostragem e análise do solo e consultar orientação técnica sobre o cultivo e as condições locais.","explanation":"Uma leitura isolada não define a necessidade ou a dose de manejo; distribuição, cultivo e características do solo importam.","hint":"Diferencie identificar uma condição de escolher uma intervenção segura e adequada.","errorFocus":"MEASUREMENT_AS_AUTOMATIC_TREATMENT","misconceptions":{"Aplicar a mesma quantidade de qualquer produto alcalino em toda a área.":["ONE_MEASUREMENT_AS_DOSE"]},"position":4},{"id":"v5-chem-ab-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"AQUARIO_MEDIDAS_REPETIDAS","statement":"Em um aquário de pesquisa, o pH medido varia ao longo do dia e a atividade dos organismos também muda. Qual desenho ajuda a avaliar essa associação?","options":["Fazer uma leitura única no horário de maior atividade e generalizar para o dia todo.","Repetir medidas em horários padronizados, registrar temperatura e outros parâmetros e comparar com um período de referência.","Alterar o pH sem supervisão até os organismos pararem de se mover.","Ignorar temperatura porque ela não pode alterar medidas químicas."],"correctAnswer":"Repetir medidas em horários padronizados, registrar temperatura e outros parâmetros e comparar com um período de referência.","explanation":"Séries temporais e condições simultâneas ajudam a interpretar variações e a distinguir efeito de pH de outras mudanças diárias.","hint":"Padronize horários e registre variáveis que também mudam ao longo do dia.","errorFocus":"TIME_VARIATION_UNCONTROLLED","misconceptions":{"Fazer uma leitura única no horário de maior atividade e generalizar para o dia todo.":["SINGLE_TIME_AS_DAILY_PATTERN"]},"position":5},{"id":"v5-chem-ab-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"DESCARGA_INDUSTRIAL_UPSTREAM","statement":"Uma equipe mede pH a montante e a jusante de uma descarga, antes e depois de um período de operação, mas também há chuva intensa apenas no segundo período. Qual conclusão é mais responsável?","options":["Qualquer diferença a jusante prova que a descarga é a única causa.","A chuva elimina a necessidade de comparar os pontos.","A comparação pode revelar um padrão, mas chuva e outras fontes precisam ser consideradas para atribuir a mudança à descarga.","O pH não pode ser influenciado por efluentes ou escoamento."],"correctAnswer":"A comparação pode revelar um padrão, mas chuva e outras fontes precisam ser consideradas para atribuir a mudança à descarga.","explanation":"A chuva pode alterar o escoamento e a química da água; uma comparação causal precisa considerar mudanças simultâneas e fontes alternativas.","hint":"Identifique o fator que mudou junto com a operação industrial.","errorFocus":"CONFOUNDED_BEFORE_AFTER_COMPARISON","misconceptions":{"Qualquer diferença a jusante prova que a descarga é a única causa.":["CONFOUNDING_IGNORED"]},"position":6},{"id":"v5-chem-ab-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"LEITURA_INDICADOR_AMOSTRA","statement":"Duas equipes usam indicadores diferentes e informam faixas de pH ligeiramente distintas para a mesma amostra. Qual é o primeiro passo para comparar os resultados?","options":["Escolher a faixa mais estreita como necessariamente correta.","Verificar as faixas de viragem, validade, procedimento e condições de uso de cada indicador.","Fazer a média dos limites sem consultar as escalas.","Concluir que a amostra mudou de pH entre duas leituras simultâneas."],"correctAnswer":"Verificar as faixas de viragem, validade, procedimento e condições de uso de cada indicador.","explanation":"Indicadores têm faixas e resoluções próprias; diferenças podem refletir o método e não uma mudança real da amostra.","hint":"Compare primeiro os instrumentos e seus limites antes de interpretar o sistema.","errorFocus":"METHOD_DIFFERENCE_AS_SAMPLE_CHANGE","misconceptions":{"Concluir que a amostra mudou de pH entre duas leituras simultâneas.":["MEASUREMENT_METHOD_VARIATION_AS_REAL_CHANGE"]},"position":7},{"id":"v5-chem-ab-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"PH_VS_ALCALINIDADE","statement":"Uma amostra tem pH 7,2, mas não há dados sobre sua composição ou resposta a adições de ácido. O que ainda não se pode concluir?","options":["O valor de pH registrado pelo método.","Sua capacidade de neutralizar uma adição, pois pH e alcalinidade/capacidade de neutralização não são a mesma medida.","Que a leitura está acima de 7 na escala usada.","Que pH descreve uma condição da solução no momento da medida."],"correctAnswer":"Sua capacidade de neutralizar uma adição, pois pH e alcalinidade/capacidade de neutralização não são a mesma medida.","explanation":"pH descreve a condição medida; alcalinidade se relaciona à capacidade de neutralizar ácido e depende de outros componentes.","hint":"Um valor inicial e uma capacidade de resistir a mudanças respondem perguntas diferentes.","errorFocus":"PH_EQUALS_ALKALINITY","misconceptions":{"O valor de pH registrado pelo método.":["PH_CONFUSED_WITH_BUFFERING_CAPACITY"]},"position":1},{"id":"v5-chem-ab-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"PROPORCAO_MOLAR_NEUTRALIZACAO","statement":"Uma solução de ácido tem concentração conhecida e reage com uma base de concentração desconhecida. Qual informação, além dos volumes, é essencial para relacionar as quantidades na neutralização?","options":["A cor do recipiente, que determina a quantidade de íons.","A igualdade entre volumes, que sempre substitui concentração e proporção.","O pH inicial sozinho, sem saber a reação ou o volume usado.","A equação balanceada, que indica a proporção estequiométrica entre os reagentes."],"correctAnswer":"A equação balanceada, que indica a proporção estequiométrica entre os reagentes.","explanation":"Para relacionar quantidades consumidas, é necessário conhecer a proporção da reação e as quantidades de matéria a partir de concentração e volume.","hint":"Verifique quantas unidades de cada reagente aparecem na equação balanceada.","errorFocus":"STOICHIOMETRIC_RATIO_OMITTED","misconceptions":{"A igualdade entre volumes, que sempre substitui concentração e proporção.":["VOLUME_REPLACES_STOICHIOMETRY"]},"position":2},{"id":"v5-chem-ab-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"PONTO_FINAL_EQUIVALENCIA","statement":"Em uma titulação supervisionada, o indicador muda de cor em certo volume. Como esse ponto se relaciona com a equivalência estequiométrica?","options":["Os dois conceitos são sempre idênticos em qualquer reação.","A equivalência é determinada apenas pela cor, sem usar a equação química.","O ponto final ocorre antes de qualquer reação entre ácido e base.","A mudança de cor define o ponto final operacional; a equivalência é a condição estequiométrica, e a proximidade depende do sistema e do indicador."],"correctAnswer":"A mudança de cor define o ponto final operacional; a equivalência é a condição estequiométrica, e a proximidade depende do sistema e do indicador.","explanation":"O ponto final é observado pelo indicador; equivalência descreve a proporção química. Um indicador adequado aproxima os pontos, mas não os torna sinônimos universais.","hint":"Separe o sinal observado do critério teórico de quantidade reagida.","errorFocus":"ENDPOINT_EQUALS_EQUIVALENCE_ALWAYS","misconceptions":{"Os dois conceitos são sempre idênticos em qualquer reação.":["OBSERVABLE_ENDPOINT_AS_EXACT_STOICHIOMETRIC_POINT"]},"position":3},{"id":"v5-chem-ab-lock-04","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"ROTULO_ALCALINO","statement":"Um rótulo informa que uma solução é alcalina. Qual conclusão de segurança é justificável apenas com essa informação?","options":["A solução é segura para tocar porque bases são inofensivas.","A solução deve ser misturada com um ácido para ficar segura.","Nenhuma avaliação completa de segurança; é preciso seguir o rótulo e considerar substância, concentração e exposição.","O pH informa a dose segura para ingestão."],"correctAnswer":"Nenhuma avaliação completa de segurança; é preciso seguir o rótulo e considerar substância, concentração e exposição.","explanation":"A categoria ácido/base não fornece sozinha avaliação de risco. Não se deve tocar, ingerir ou misturar produtos para testá-los.","hint":"Não transforme uma classificação química em instrução de uso.","errorFocus":"ACID_BASE_LABEL_AS_SAFETY_GUIDE","misconceptions":{"A solução é segura para tocar porque bases são inofensivas.":["BASICITY_AS_HARMLESSNESS"]},"position":4},{"id":"v5-chem-ab-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SERIE_MEDIDAS_PH","statement":"Um relatório apresenta uma única leitura de pH sem identificar instrumento, calibração, temperatura ou ponto de coleta. Qual crítica metodológica é mais relevante?","options":["Uma única leitura é sempre suficiente se tiver muitas casas decimais.","O pH não depende de método nem de condições de coleta.","Faltam informações para avaliar comparabilidade, incerteza e representatividade da leitura.","A ausência de detalhes prova que a água é neutra."],"correctAnswer":"Faltam informações para avaliar comparabilidade, incerteza e representatividade da leitura.","explanation":"Método, condições e local ajudam a interpretar se a medida é confiável e representa o sistema que o relatório descreve.","hint":"Pergunte o que outra equipe precisaria saber para repetir a medida.","errorFocus":"MISSING_MEASUREMENT_PROVENANCE","misconceptions":{"Uma única leitura é sempre suficiente se tiver muitas casas decimais.":["NUMERIC_PRECISION_AS_REPRESENTATIVENESS"]},"position":5},{"id":"v5-chem-ab-review-01","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"PH_AMOSTRAS_CAFE","statement":"Duas amostras aquosas têm pH 2 e pH 4, medidos sob condições comparáveis. Qual comparação aproximada é correta?","options":["A amostra de pH 4 tem cem vezes a atividade de H+.","A atividade de H+ na amostra de pH 2 é cem vezes a da amostra de pH 4.","A primeira é apenas duas vezes mais ácida porque a diferença é 2.","As duas têm a mesma atividade de H+ porque são ácidas."],"correctAnswer":"A atividade de H+ na amostra de pH 2 é cem vezes a da amostra de pH 4.","explanation":"Duas unidades correspondem a dois fatores de dez; o menor pH corresponde à atividade de H+ maior.","hint":"Calcule 10 x 10 e confira qual valor de pH é menor.","errorFocus":"MULTIPLIER_DIRECTION_AND_SCALE","misconceptions":{"A amostra de pH 4 tem cem vezes a atividade de H+.":["LOWER_PH_DIRECTION_REVERSED"]},"position":1},{"id":"v5-chem-ab-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"FITA_PH_FAIXA","statement":"Uma fita apresenta cor compatível tanto com pH 6 quanto com pH 7 na cartela. Qual relato é mais honesto?","options":["A amostra tem pH exatamente 6,50 sem incerteza.","A fita prova que a solução contém somente água.","A leitura visual ficou aproximadamente entre as referências 6 e 7; outro método pode ser necessário para maior precisão.","O resultado não pode ser registrado porque não é exato."],"correctAnswer":"A leitura visual ficou aproximadamente entre as referências 6 e 7; outro método pode ser necessário para maior precisão.","explanation":"Incerteza não impede registrar um resultado útil; ela deve ser comunicada com o intervalo e o método.","hint":"Uma faixa bem registrada é melhor que uma casa decimal inventada.","errorFocus":"UNCERTAINTY_OMITTED","misconceptions":{"A amostra tem pH exatamente 6,50 sem incerteza.":["VISUAL_MIDPOINT_AS_EXACT"]},"position":2},{"id":"v5-chem-ab-review-03","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"MEDIDOR_CONTROLE_QUALIDADE","statement":"Um medidor indica pH 7,01 em duas amostras, mas a verificação com solução-padrão falha. Qual conclusão deve ser adiada?","options":["A de que o instrumento apresentou números no visor.","A de que o procedimento de calibração precisa ser revisado.","A de que os valores são comparáveis e suficientemente confiáveis até corrigir o procedimento e repetir a verificação.","A de que duas casas decimais garantem que a leitura esteja correta."],"correctAnswer":"A de que os valores são comparáveis e suficientemente confiáveis até corrigir o procedimento e repetir a verificação.","explanation":"Números exibidos não bastam quando uma verificação de qualidade falha; a medição precisa ser corrigida antes da comparação.","hint":"Separe o que o visor mostrou da validação do instrumento.","errorFocus":"FAILED_CALIBRATION_IGNORED","misconceptions":{"A de que duas casas decimais garantem que a leitura esteja correta.":["DISPLAY_PRECISION_AS_ACCURACY"]},"position":3},{"id":"v5-chem-ab-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"MESMO_PH_DIFERENTE_RESPOSTA","statement":"Duas soluções têm o mesmo pH inicial, mas uma muda muito mais após receber porções iguais de ácido em condições controladas. O que isso demonstra?","options":["O mesmo pH inicial não garante a mesma capacidade de neutralização ou composição.","A solução que mudou mais tinha necessariamente pH inicial menor.","As duas soluções são quimicamente idênticas porque começaram com o mesmo pH.","A porção de ácido não pode ter influenciado nenhuma das amostras."],"correctAnswer":"O mesmo pH inicial não garante a mesma capacidade de neutralização ou composição.","explanation":"Valores iniciais iguais não implicam resposta igual a uma perturbação; outros constituintes determinam a capacidade de resistir à mudança.","hint":"Compare estado inicial com resposta à mesma perturbação.","errorFocus":"SAME_STATE_AS_SAME_SYSTEM","misconceptions":{"As duas soluções são quimicamente idênticas porque começaram com o mesmo pH.":["EQUAL_PH_AS_IDENTICAL_COMPOSITION"]},"position":4},{"id":"v5-chem-ab-review-05","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"TITULACAO_DADOS_INCOMPLETOS","statement":"Uma anotação registra que o indicador mudou de cor após certa quantidade de titulante, mas omite concentração e equação da reação. O que ainda não se pode determinar adequadamente?","options":["Que ocorreu uma mudança de cor observada.","Que o método usou um indicador.","A concentração da amostra usando apenas o volume, sem conhecer a concentração do titulante.","A quantidade estequiométrica de reagente consumida e a concentração desconhecida."],"correctAnswer":"A quantidade estequiométrica de reagente consumida e a concentração desconhecida.","explanation":"Cálculo quantitativo requer concentração conhecida, volumes e proporção da reação balanceada; a cor sozinha não fornece essas informações.","hint":"Liste os dados necessários para converter volume em quantidade de matéria.","errorFocus":"TITRATION_WITHOUT_CONCENTRATION_OR_STOICHIOMETRY","misconceptions":{"A concentração da amostra usando apenas o volume, sem conhecer a concentração do titulante.":["UNKNOWN_TITRANT_AMOUNT_ASSUMED"]},"position":5},{"id":"v5-chem-ab-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"PEIXES_METAL_TEMPERATURA","statement":"Depois de uma chuva, um trecho apresenta pH menor, mais metal dissolvido e menos peixes observados. Qual síntese inicial é mais rigorosa?","options":["A chuva prova que apenas o pH matou todos os peixes.","Os dados sugerem hipóteses sobre estressores que podem interagir; medidas repetidas, referência e outras variáveis ajudam a testar mecanismos.","A presença de metal exclui qualquer efeito possível de pH.","A contagem de peixes identifica a substância que entrou na água."],"correctAnswer":"Os dados sugerem hipóteses sobre estressores que podem interagir; medidas repetidas, referência e outras variáveis ajudam a testar mecanismos.","explanation":"pH, metais e respostas biológicas podem estar relacionados; o padrão observado não identifica sozinho a fonte ou a causa exclusiva.","hint":"Considere interações entre estressores e procure evidências independentes para cada hipótese.","errorFocus":"MULTIPLE_STRESSORS_COLLAPSED","misconceptions":{"A chuva prova que apenas o pH matou todos os peixes.":["CORRELATION_AS_EXCLUSIVE_CAUSE"]},"position":6},{"id":"v5-chem-ab-review-07","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"PRODUTO_LIMPEZA_PH","statement":"Uma pessoa vê que um produto de limpeza tem pH básico e decide misturá-lo com outro produto ácido para neutralizá-lo. Qual orientação é correta?","options":["Não misturar produtos; seguir o rótulo e as instruções de segurança, pois podem ocorrer reações perigosas.","Misturar em partes iguais porque o pH se cancela aritmeticamente.","Adicionar água até a cor desaparecer e considerar a mistura segura.","Testar primeiro com a pele para verificar se houve neutralização."],"correctAnswer":"Não misturar produtos; seguir o rótulo e as instruções de segurança, pois podem ocorrer reações p